 private SavannahConfig() {}
 public static double maxHealth(int bond) { return (40+2*(clampBond(bond)-1))*HEALTH_SCALE.get()*(HIGH_POWER.get()?1.5:1); }
 public static double meleeDamage(int bond) { return new double[]{6,6.4,6.8,7.2,7.5}[clampBond(bond)-1]*(HIGH_POWER.get()?1.25:1); }
 public static float pounceDamage(int bond) { return (float)(new double[]{8,8.5,9,9.5,10}[clampBond(bond)-1]*(HIGH_POWER.get()?1.25:1)); }
 public static int downedTicks(int bond) { return switch(clampBond(bond)){case 2->DOWNED_LEVEL_2.get()*20;case 3->DOWNED_LEVEL_3.get()*20;case 4->DOWNED_LEVEL_4.get()*20;case 5->DOWNED_LEVEL_5.get()*20;default->DOWNED_LEVEL_1.get()*20;}; }
 private static int clampBond(int b) { return Math.clamp(b,1,5); }
 public static boolean isFood(ItemStack stack, boolean taming) { return !stack.isEmpty() && (taming?TAMING_FOODS:HEALING_FOODS).get().contains(BuiltInRegistries.ITEM.getKey(stack.getItem()).toString()); }
